const NEGATE = /\b(no|nope|not|don'?t|wait|cancel|nahi|nahin|mat|ruk)\b|نہیں|مت/i;
// A yes only counts as the answer to Sera's own read-back (f0 Reply marks the chat when her reply repeats a time and a doctor
